begin;

alter table public.profiles drop constraint if exists profiles_id_fkey;

alter table public.profiles add column if not exists email text;

create unique index if not exists profiles_email_unique on public.profiles (lower(email)) where email is not null;


on conflict (id) do update set code = excluded.code, name = excluded.name, attribute_schema = excluded.attribute_schema, active = true;

on conflict (id) do update set code = excluded.code, name = excluded.name, address = excluded.address, active = true;


create table if not exists public.purchase_invoices (
  id uuid primary key default gen_random_uuid(), invoice_number text not null unique, delivery_reference text, source_order text,
  invoice_date date, delivery_date date, document_type text not null, merchandise_amount numeric(14,2) not null default 0,
  packaging_amount numeric(14,2) not null default 0, invoice_total numeric(14,2) not null default 0,
  receipt_status text not null default 'draft', source_file_name text, review_note text,
  supplier_id uuid references public.suppliers(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

create table if not exists public.purchase_charges (
  id uuid primary key default gen_random_uuid(), invoice_id uuid not null references public.purchase_invoices(id) on delete restrict,
  charge_type text not null, supplier_item_code text, quantity numeric(14,3) not null, unit_cost numeric(14,4) not null,
  amount numeric(14,2) not null, allocation_status text not null, notes text, created_at timestamptz not null default now()
);

create table if not exists public.sheet_sync_outbox (
  id bigint generated always as identity primary key, entity_table text not null, entity_key text not null,
  operation text not null, payload jsonb not null, status text not null default 'pending', attempts integer not null default 0,
  created_at timestamptz not null default now(), processed_at timestamptz, error_message text
);

create index if not exists sheet_sync_outbox_pending_idx on public.sheet_sync_outbox(status, created_at);
















































































































































create or replace function public.enqueue_sheet_sync_event() returns trigger language plpgsql security definer set search_path = public as $$
begin
  values (TG_TABLE_NAME, coalesce((to_jsonb(new)->>'id'), (to_jsonb(new)->>'variant_id'), (to_jsonb(new)->>'invoice_number'), ''), TG_OP, to_jsonb(new));
  return new;
end;
$$;

drop trigger if exists queue_products_sheet_sync on public.products;

create trigger queue_products_sheet_sync after insert or update on public.products for each row execute function public.enqueue_sheet_sync_event();

drop trigger if exists queue_product_variants_sheet_sync on public.product_variants;

create trigger queue_product_variants_sheet_sync after insert or update on public.product_variants for each row execute function public.enqueue_sheet_sync_event();

drop trigger if exists queue_inventory_transactions_sheet_sync on public.inventory_transactions;

create trigger queue_inventory_transactions_sheet_sync after insert or update on public.inventory_transactions for each row execute function public.enqueue_sheet_sync_event();

drop trigger if exists queue_inventory_transaction_lines_sheet_sync on public.inventory_transaction_lines;

create trigger queue_inventory_transaction_lines_sheet_sync after insert or update on public.inventory_transaction_lines for each row execute function public.enqueue_sheet_sync_event();

drop trigger if exists queue_variant_private_costs_sheet_sync on public.variant_private_costs;

create trigger queue_variant_private_costs_sheet_sync after insert or update on public.variant_private_costs for each row execute function public.enqueue_sheet_sync_event();

drop trigger if exists queue_purchase_invoices_sheet_sync on public.purchase_invoices;

create trigger queue_purchase_invoices_sheet_sync after insert or update on public.purchase_invoices for each row execute function public.enqueue_sheet_sync_event();

drop trigger if exists queue_purchase_charges_sheet_sync on public.purchase_charges;

create trigger queue_purchase_charges_sheet_sync after insert or update on public.purchase_charges for each row execute function public.enqueue_sheet_sync_event();

alter table public.purchase_invoices enable row level security;

alter table public.purchase_charges enable row level security;

alter table public.sheet_sync_outbox enable row level security;

revoke all on public.purchase_invoices, public.purchase_charges, public.sheet_sync_outbox from anon, authenticated;

commit;

